#
# t_convolution.jl
#
# To compare the Type-1 (C = A ∗ B) and Type-2 (C = A ∗ f ∗ B) full contour
# convolutions with NESSi, for k = 1:5, size = 1 and 2.
#
# NESSi reference: libcntr/cntr/cntr_convolution_impl.hpp:1897-2683,
# 2724-2849, 3123-3129; hermitian conjugation of matrix elements:
# libcntr/cntr/cntr_elements.hpp:38-80. Data are generated by
# .nessi/kbref/convolution.cpp, whose closed-form inputs are rebuilt here
# with exactly the same formulas (nothing is read back from the output).
#
# The hermitian shorthand APIs are used, i.e. Acc = A and Bcc = B.
#

using LinearAlgebra

const CONV_NT = 30
const CONV_NTAU = 60
const CONV_BETA = 4.0
const CONV_H = 0.05
const CONV_MU = 0.1

# Time-independent parts of the hermitian Hamiltonians H_A0 and H_B0
function conv_hamiltonian(which::Int)
    if which == 0
        return C64[-0.5 0.2+0.1im; 0.2-0.1im 0.4]
    else
        return C64[0.3 0.25-0.05im; 0.25+0.05im -0.2]
    end
end

# φ(t) = ∫₀ᵗ a(t'), with a_A(t) = 0.3 sin(t) and a_B(t) = 0.2 sin(2t)
conv_phase(which::Int, t::F64) =
    which == 0 ? 0.3 * (1.0 - cos(t)) : 0.1 * (1.0 - cos(2.0 * t))

# Time-dependent, non-hermitian middle function f(t)
conv_middle(t::F64) = C64[1.0+0.2t 0.1+0.3t*im; -0.2+0.05im 0.8]

# Free fermionic Green's function for H(t) = H_0 + a(t) I
function conv_green(which::Int, size::Int)
    C = Cn(CONV_NT + 1, CONV_NTAU + 1, size, size, CONV_NT * CONV_H, CONV_BETA)
    G = ℱ(C, FERMI)
    #
    ϵ = conv_hamiltonian(which)[1:size,1:size] - CONV_MU * I
    vals, V = eigen(Hermitian(ϵ))
    fd(g) = V * diagm(C64.(g)) * V'
    #
    for q = 0:CONV_NTAU
        τ = q * CONV_BETA / CONV_NTAU
        G.mat[q+1] = fd(-exp.(-vals .* τ) ./ (1.0 .+ exp.(-CONV_BETA .* vals)))
    end
    #
    U = [fd(exp.(-im .* vals .* (i * CONV_H))) *
         exp(-im * conv_phase(which, i * CONV_H)) for i = 0:CONV_NT]
    ρ = fd(1.0 ./ (1.0 .+ exp.(CONV_BETA .* vals)))
    for i = 0:CONV_NT
        for j = 0:i
            G.ret[i+1,j+1] = -im * U[i+1] * U[j+1]'
        end
        for j = i:CONV_NT
            G.less[i+1,j+1] = im * U[i+1] * ρ * U[j+1]'
        end
        for q = 0:CONV_NTAU
            τ = q * CONV_BETA / CONV_NTAU
            g = exp.(vals .* τ) ./ (1.0 .+ exp.(CONV_BETA .* vals))
            G.lmix[i+1,q+1] = im * U[i+1] * fd(g)
        end
    end
    return C, G
end

function conv_middle_function(C::Cn, size::Int)
    f = Cf(C, zero(C64))
    f[0] = conv_middle(0.0)[1:size,1:size]
    for i = 0:CONV_NT
        f[i+1] = conv_middle(i * CONV_H)[1:size,1:size]
    end
    return f
end

@testset verbose = true "NESSi: convolution" begin
    # 2x2 cases first: they expose the hermitian conjugation semantics of
    # Acc/Bcc (Type-1) and the start-up branch of Type-2.
    for size in (2, 1), type in (1, 2), k = 1:5
        name = "convolution_type$(type)_size$(size)_k$(k)"
        @testset "$name" begin
            ref = read_kbref(joinpath(@__DIR__, "data", name * ".dat"))
            @test ref.metadata["case"] == name
            @test parse(Int, ref.metadata["solve_order"]) == k
            @test parse(Int, ref.metadata["size1"]) == size
            #
            C, A = conv_green(0, size)
            _, B = conv_green(1, size)
            Cv = ℱ(C, FERMI)
            if type == 1
                convolution(Cv, A, B, k, CONV_BETA, CONV_H)
            else
                f = conv_middle_function(C, size)
                convolution(Cv, A, f, B, k, CONV_BETA, CONV_H)
            end
            #
            errs = test_kbref(Cv, ref; atol = 1e-10, rtol = 1e-10)
            @printf("  %-30s max err: mat %.2e ret %.2e tv %.2e les %.2e\n",
                    name, errs["mat"], errs["ret"], errs["tv"], errs["les"])
        end
    end
end
